#include "native_model.hpp"
#include "native_study.hpp"
#include <iostream>
#include <string>
namespace wordcard {extern std::string native_learning_json();}
static wordcard::J pageJson(const wordcard::WebPage&p){using namespace wordcard;J out{{"title",p.title},{"route",p.route},{"key",p.key},{"typed",p.typed},{"prompt",p.prompt},{"gapMask",p.gap_mask},{"toast",p.toast},{"keyboard",p.keyboard},{"shift",p.shift},{"symbols",p.symbols},{"canSubmit",p.can_submit},{"corrupt",p.corrupt},{"blocks",J::array()},{"top",J::array()},{"tabs",J::array()},{"actions",J::array()}};for(const auto&a:p.actions)out["actions"].push_back(J::parse(a));for(const auto&b:p.blocks)out["blocks"].push_back(J{{"kind",b.kind},{"text",b.text},{"area",b.area},{"action",b.action},{"enabled",b.enabled},{"selected",b.selected},{"primary",b.primary},{"role",b.role},{"detail",b.detail}});for(const auto*kind:{"top","tabs"})for(const auto&b:std::string(kind)=="top"?p.top:p.tabs)out[kind].push_back(J{{"text",b.text},{"action",b.action},{"selected",b.selected},{"enabled",b.enabled}});return out;}
int main(){using namespace wordcard;const auto data=J::parse(native_learning_json());NativeModel model(data);std::string line;while(std::getline(std::cin,line)){try{const auto q=J::parse(line);model.now=num(q,"now");J out;if(q.contains("viewContext")){int writes=0;NativeStudy study([&](const std::string&,const std::string&){++writes;return !flag(q,"failWrite");});out["entered"]=study.enter(q["viewContext"].dump());if(q.contains("action"))out["handled"]=study.dispatch(q["action"].dump());if(q.contains("input"))out["typed"]=study.type(str(q,"input"));out["page"]=pageJson(study.page());out["context"]=J::parse(study.context());out["status"]=J::parse(study.status());out["writes"]=writes;}else if(q.contains("snapshot")){model.state=q.at("state");out=model.snapshot(q.at("snapshot"));}else if(q.contains("normal"))out=J{{"normal",NativeModel::normal(str(q,"normal"))}};else if(q.contains("gap"))out=model.gap(str(q,"gap"),num(q,"serial"));else{model.state=q.at("state");out["validBefore"]=model.validate(model.state);try{J draft=model.state;out["handled"]=model.mutate(draft,str(q,"method"),field(q,"args"));out["validAfter"]=model.validate(draft);out["state"]=draft;}catch(const std::exception&e){out["error"]=e.what();out["state"]=model.state;}}std::cout<<out.dump()<<'\n';}catch(const std::exception&e){std::cout<<J{{"fatal",e.what()}}.dump()<<'\n';}}}
